h1.title{font-family:'Bodoni Moda',serif;font-weight:500;font-size:clamp(3.2rem,13vw,11rem);line-height:.88;letter-spacing:-.01em;margin:.3em 0 .1em}
h1.title em{font-style:italic;color:var(--burgundy);font-weight:400}
.deck{font-size:clamp(1.1rem,2.3vw,1.55rem);max-width:46ch;color:var(--amber-deep);margin-top:1.2rem;font-family:'Bodoni Moda',serif;font-style:italic}
.hero-meta{margin-top:3rem;display:flex;flex-wrap:wrap;gap:2.5rem;font-family:'IBM Plex Mono',monospace;font-size:.68rem;letter-spacing:.18em;text-transform:uppercase;color:var(--amber-deep)}
.hero-meta span b{display:block;font-size:1.5rem;font-family:'Bodoni Moda',serif;letter-spacing:0;text-transform:none;color:var(--ink);font-weight:600}
.glass{position:absolute;top:9%;right:9%;font-size:7rem;opacity:.1;transform:rotate(-6deg)}

/* ---------- HEALTH BANNER ---------- */
.banner{background:var(--burgundy);color:var(--paper);padding:1.1rem clamp(1.5rem,7vw,10rem);font-size:.92rem;display:flex;gap:.8rem;align-items:center;border-bottom:2px solid var(--ink)}
.banner b{font-family:'IBM Plex Mono',monospace;letter-spacing:.1em;text-transform:uppercase;font-size:.7rem}

/* ---------- NAV ---------- */
nav.toc{position:sticky;top:0;z-index:50;background:var(--ink);color:var(--paper);display:flex;gap:0;overflow-x:auto;border-bottom:2px solid var(--ink);font-family:'IBM Plex Mono',monospace;font-size:.67rem;letter-spacing:.13em;text-transform:uppercase}
nav.toc a{color:var(--paper);text-decoration:none;padding:1rem 1.2rem;white-space:nowrap;border-right:1px solid rgba(236,228,214,.14);transition:.25s;flex-shrink:0}
nav.toc a:hover{background:var(--amber);color:var(--ink)}

/* ---------- SECTIONS ---------- */
section{padding:clamp(3rem,8vw,7rem) clamp(1.5rem,7vw,10rem);border-bottom:1px solid var(--line)}
.sec-head{display:flex;align-items:baseline;gap:1.2rem;margin-bottom:1.8rem}
.sec-num{font-family:'IBM Plex Mono',monospace;font-size:.82rem;color:var(--gold);letter-spacing:.2em}
h2{font-family:'Bodoni Moda',serif;font-weight:500;font-size:clamp(2rem,5vw,3.6rem);line-height:1;letter-spacing:-.01em}
h3{font-family:'Bodoni Moda',serif;font-weight:600;font-size:1.6rem;margin:2rem 0 .6rem;color:var(--amber-deep)}
p{max-width:68ch;margin-bottom:1.1rem}
.lead{font-size:1.22rem;max-width:60ch}
.dropcap::first-letter{font-family:'Bodoni Moda',serif;font-weight:500;float:left;font-size:4.8rem;line-height:.76;padding:.06em .12em 0 0;color:var(--burgundy)}

/* timeline */
.timeline{border-left:2px solid var(--line);margin:2rem 0 0}
.tl-item{position:relative;padding:0 0 2rem 2.2rem}
.tl-item::before{content:"";position:absolute;left:-7px;top:.45rem;width:12px;height:12px;border-radius:50%;background:var(--amber);border:2px solid var(--ink)}
.tl-year{font-family:'IBM Plex Mono',monospace;font-size:.76rem;letter-spacing:.18em;color:var(--gold)}

/* cards */
.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:1.2rem;margin-top:2rem}
.card{background:var(--paper-2);border:1px solid var(--line);padding:1.6rem 1.5rem;position:relative;overflow:hidden}
.card::after{content:"";position:absolute;top:0;right:0;width:44px;height:44px;background:var(--amber);clip-path:polygon(100% 0,0 0,100% 100%)}
.card .ic{font-size:1.7rem;display:block;margin-bottom:.5rem}
.card h4{font-family:'Bodoni Moda',serif;font-size:1.25rem;margin-bottom:.3rem;font-weight:600}
.card p{font-size:.95rem;margin:0}

/* spectrum */
.spectrum{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:0;margin-top:2rem;border:2px solid var(--ink)}
.swatch{padding:1.4rem 1.1rem;color:#fff;min-height:150px;display:flex;flex-direction:column;justify-content:flex-end;border-right:1px solid rgba(255,255,255,.18)}
.swatch:last-child{border-right:none}
.swatch .lbl{font-family:'IBM Plex Mono',monospace;font-size:.62rem;letter-spacing:.14em;text-transform:uppercase;opacity:.85}
.swatch .nm{font-family:'Bodoni Moda',serif;font-size:1.4rem;font-weight:600;line-height:1}
.swatch small{font-size:.82rem;opacity:.92;margin-top:.3rem}

/* methods */
.method{margin-top:3.5rem;border:2px solid var(--ink);background:var(--paper-2);box-shadow:8px 8px 0 var(--shadow)}
.method-top{display:grid;grid-template-columns:1fr}
@media(min-width:840px){.method-top{grid-template-columns:1.1fr 1fr}}
.method-id{padding:2rem 2rem 1.5rem;border-bottom:2px solid var(--ink)}
@media(min-width:840px){.method-id{border-bottom:none;border-right:2px solid var(--ink)}}
.method-id .tag{font-family:'IBM Plex Mono',monospace;font-size:.67rem;letter-spacing:.2em;text-transform:uppercase;color:var(--gold)}
.method-id h3{margin:.3rem 0 .8rem;font-size:2.1rem;color:var(--ink)}
.specs{display:flex;flex-wrap:wrap;gap:.5rem;margin-top:1rem}
.spec{font-family:'IBM Plex Mono',monospace;font-size:.63rem;letter-spacing:.05em;text-transform:uppercase;background:var(--ink);color:var(--paper);padding:.35rem .6rem}
.spec.alt{background:transparent;color:var(--ink);border:1px solid var(--ink)}
.method-blurb{padding:2rem}
.method-blurb p{font-size:1rem}

.steps{counter-reset:step;list-style:none;padding:1.8rem 2rem 2rem;border-top:2px dashed var(--line)}
.steps li{counter-increment:step;position:relative;padding-left:3rem;margin-bottom:1rem;font-size:1rem;max-width:64ch}
.steps li::before{content:counter(step,decimal-leading-zero);position:absolute;left:0;top:0;font-family:'IBM Plex Mono',monospace;font-size:.85rem;color:var(--paper);background:var(--burgundy);width:2rem;height:2rem;display:flex;align-items:center;justify-content:center;border-radius:50%}

.tradeoffs{display:grid;grid-template-columns:1fr;border-top:2px solid var(--ink)}
@media(min-width:680px){.tradeoffs{grid-template-columns:1fr 1fr}}
.pros,.cons{padding:1.6rem 2rem}
.pros{background:rgba(184,118,42,.12)}
.cons{background:rgba(107,36,54,.08);border-top:1px solid var(--line)}
@media(min-width:680px){.cons{border-top:none;border-left:1px solid var(--ink)}}
.toff-h{font-family:'IBM Plex Mono',monospace;font-size:.7rem;letter-spacing:.2em;text-transform:uppercase;margin-bottom:.8rem}
.pros .toff-h{color:var(--amber-deep)}
.cons .toff-h{color:var(--burgundy)}
.tradeoffs ul{list-style:none}
.tradeoffs li{font-size:.95rem;padding:.3rem 0 .3rem 1.4rem;position:relative}
.pros li::before{content:"+";position:absolute;left:0;color:var(--amber-deep);font-weight:700}
.cons li::before{content:"–";position:absolute;left:0;color:var(--burgundy);font-weight:700}

blockquote{font-family:'Bodoni Moda',serif;font-style:italic;font-size:clamp(1.4rem,3.4vw,2.3rem);line-height:1.3;max-width:26ch;margin:3rem auto;text-align:center;color:var(--amber-deep);position:relative;font-weight:400}
blockquote::before{content:"❧";font-size:2rem;color:var(--amber);display:block;margin-bottom:.4rem}

table.ratio{width:100%;border-collapse:collapse;margin-top:2rem;font-size:.95rem}
table.ratio th,table.ratio td{border:1px solid var(--line);padding:.7rem 1rem;text-align:left}
table.ratio th{background:var(--ink);color:var(--paper);font-family:'IBM Plex Mono',monospace;font-size:.65rem;letter-spacing:.1em;text-transform:uppercase;font-weight:400}
table.ratio tr:nth-child(even){background:var(--paper-2)}
table.ratio td:first-child{font-weight:700;color:var(--amber-deep)}

footer{padding:4rem clamp(1.5rem,7vw,10rem);background:var(--ink);color:var(--paper);text-align:center}
footer .big{font-family:'Bodoni Moda',serif;font-style:italic;font-size:clamp(1.5rem,4vw,2.4rem);margin-bottom:1rem}
footer p{margin:0 auto 1rem;color:#cabda4;font-size:.95rem;max-width:60ch}
footer .resources{font-family:'IBM Plex Mono',monospace;font-size:.72rem;letter-spacing:.1em;color:var(--gold);margin-top:1.5rem}

.reveal{opacity:0;transform:translateY(28px);transition:opacity .7s ease,transform .7s ease}
.reveal.in{opacity:1;transform:none}

:root{
  --soot:#16130d;
  --soot-raised:#1f1a12;
  --soot-sunk:#120f0a;
  --line:#33291d;
  --line-soft:#261f16;
  --bone:#ece5d6;
  --bone-dim:#b3a893;
  --ash:#7d735f;
  --ember:#d0602e;
  --ember-soft:#e5924f;
  --ember-deep:#8f3d1c;
  --ice:#8fb0c0;
  --font-display:'Fraunces',Georgia,'Times New Roman',serif;
  --font-body:'Newsreader',Georgia,serif;
  --font-mono:'JetBrains Mono','SF Mono',ui-monospace,monospace;
}

*{box-sizing:border-box;margin:0;padding:0}
html{-webkit-text-size-adjust:100%}
body{
  background:var(--soot);
  color:var(--bone);
  font-family:var(--font-body);
  font-size:18px;
  line-height:1.6;
  font-optical-sizing:auto;
  -webkit-font-smoothing:antialiased;
  background-image:radial-gradient(120% 80% at 50% -10%, #1d1810 0%, var(--soot) 60%);
}
.wrap{max-width:880px;margin:0 auto;padding:0 26px}

.eyebrow{
  font-family:var(--font-mono);
  font-size:.72rem;
  letter-spacing:.32em;
  text-transform:uppercase;
  color:var(--ash);
  font-weight:500;
}

/* hero */
.hero{padding:92px 0 40px}
.hero .eyebrow{color:var(--ember-soft)}
.hero h1{
  font-family:var(--font-display);
  font-weight:900;
  font-size:clamp(2.7rem,7.4vw,5.1rem);
  line-height:.96;
  letter-spacing:-.025em;
  margin:22px 0 26px;
}
.hero h1 em{font-style:italic;color:var(--ember-soft);font-weight:600}
.lede{font-size:1.22rem;color:var(--bone-dim);max-width:62ch;line-height:1.55}
.lede strong{color:var(--bone);font-weight:600}

/* legend */
.legend{
  margin-top:34px;padding-top:26px;border-top:1px solid var(--line-soft);
  display:flex;flex-wrap:wrap;gap:18px 32px;
}
.legend-item{
  font-family:var(--font-mono);font-size:.74rem;color:var(--ash);
  letter-spacing:.02em;display:flex;align-items:center;gap:9px;
}
.legend-item b{color:var(--bone-dim);font-weight:500;letter-spacing:.14em;text-transform:uppercase;font-size:.68rem}
.lg-bar{width:26px;height:7px;border-radius:2px;background:linear-gradient(90deg,var(--ember-deep),var(--ember))}
.lg-dots{color:var(--ember-soft);letter-spacing:1px}
.lg-ice{color:var(--ice)}
.lg-hot{color:var(--ember)}
.lg-dia{color:var(--ember);font-size:.7rem}

/* section heads */
.sec{padding:56px 0 8px}
.sec-head{margin-bottom:32px}
.sec-head .eyebrow{display:block;margin-bottom:12px}
.sec-head h2{
  font-family:var(--font-display);font-weight:600;
  font-size:clamp(1.7rem,4vw,2.4rem);letter-spacing:-.01em;line-height:1.05;
}
.sec-head p{color:var(--bone-dim);margin-top:10px;max-width:58ch;font-size:1.02rem}

/* principles */
.principles{
  display:grid;grid-template-columns:repeat(2,1fr);gap:1px;
  background:var(--line-soft);border:1px solid var(--line-soft);
  border-radius:12px;overflow:hidden;
}
.pr{background:var(--soot-raised);padding:26px 24px 28px}
.pr-n{font-family:var(--font-mono);font-size:.72rem;color:var(--ember);letter-spacing:.1em;margin-bottom:12px}
.pr h3{font-family:var(--font-display);font-weight:600;font-size:1.16rem;margin-bottom:9px;line-height:1.2}
.pr p{font-size:.97rem;color:var(--bone-dim);line-height:1.5}
.pr p .fix{color:var(--bone)}

/* tiers */
.tier{margin-top:46px}
.tier:first-child{margin-top:8px}
.tier-head{
  display:flex;align-items:baseline;gap:20px;
  padding-bottom:18px;margin-bottom:22px;border-bottom:1px solid var(--line);
}
.tier-letter{font-family:var(--font-display);font-weight:900;font-size:clamp(2.6rem,8vw,3.7rem);line-height:.8;letter-spacing:-.03em}
.tier-meta{padding-bottom:4px}
.tier-title{font-family:var(--font-display);font-weight:600;font-size:1.28rem;letter-spacing:-.01em}
.tier-sub{font-family:var(--font-mono);font-size:.72rem;letter-spacing:.06em;color:var(--ash);margin-top:4px;text-transform:uppercase}

.cards{display:flex;flex-direction:column;gap:16px}
.mix{
  background:var(--soot-raised);border:1px solid var(--line-soft);
  border-radius:12px;padding:22px 24px 20px;transition:border-color .25s ease;
}
.mix:hover{border-color:var(--line)}
.mix.mine{border-color:#4a3320;background:linear-gradient(180deg,#241b12,var(--soot-raised))}

.mix-top{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:16px}
.mix-name{font-family:var(--font-display);font-weight:600;font-size:1.34rem;letter-spacing:-.01em;line-height:1.1}
.badge{
  font-family:var(--font-mono);font-size:.6rem;letter-spacing:.18em;text-transform:uppercase;
  color:var(--soot);background:var(--ember);padding:4px 8px 3px;border-radius:4px;font-weight:700;white-space:nowrap;
}

/* meta: meter + stat chips */
.meta{display:flex;flex-direction:column;gap:15px;margin-bottom:15px}
.meter-block{width:100%}
.meter-label{
  display:flex;justify-content:space-between;align-items:baseline;
  font-family:var(--font-mono);font-size:.66rem;letter-spacing:.12em;text-transform:uppercase;color:var(--ash);margin-bottom:7px;
}
.meter-label .load{color:var(--bone-dim);letter-spacing:.04em}
.track{height:8px;background:var(--soot-sunk);border-radius:5px;overflow:hidden;box-shadow:inset 0 1px 2px rgba(0,0,0,.4)}
.fill{
  height:100%;width:0;border-radius:5px;
  background:linear-gradient(90deg,var(--ember-deep) 0%,var(--ember) 62%,var(--ember-soft) 100%);
  transition:width 1.1s cubic-bezier(.22,.61,.36,1);
}
.stat-row{display:flex;flex-wrap:wrap;gap:12px 26px}
.stat{display:flex;align-items:center;gap:9px}
.stat-cap{font-family:var(--font-mono);font-size:.66rem;letter-spacing:.12em;text-transform:uppercase;color:var(--ash)}
.dots{font-family:var(--font-mono);font-size:.82rem;letter-spacing:2px;color:var(--ember-soft)}
.dots .off{color:#3c3225}
.mask-word{font-family:var(--font-mono);font-size:.74rem;color:var(--bone-dim)}

.why{color:var(--bone-dim);font-size:1.02rem;line-height:1.5;margin-bottom:16px}

.formula{
  background:var(--soot-sunk);border:1px solid var(--line-soft);border-radius:8px 8px 0 0;
  border-bottom:none;padding:15px 16px 13px;
  font-family:var(--font-mono);font-size:.82rem;line-height:1.5;color:var(--bone-dim);
}
.f-line{display:flex;gap:10px;align-items:baseline;padding:2px 0}
.f-mark{color:var(--ember);font-weight:700;flex:0 0 auto;width:12px}
.f-line.go .f-mark{color:var(--ember-soft)}
.f-main{flex:1 1 auto}
.f-main b{color:var(--bone);font-weight:500}
.f-note{color:var(--ash);flex:0 0 auto;font-size:.76rem}
.f-line.go .f-main{color:var(--bone)}

/* prep strip: freeze + reheat */
.prep{
  background:#100d08;border:1px solid var(--line-soft);border-radius:0 0 8px 8px;
  padding:13px 16px;display:flex;flex-direction:column;gap:7px;
}
.p-line{display:flex;align-items:baseline;gap:11px;font-family:var(--font-mono);font-size:.76rem;color:var(--bone-dim);line-height:1.45}
.p-mark{flex:0 0 auto;font-size:.9rem;line-height:1}
.p-mark.fz{color:var(--ice)}
.p-mark.hot{color:var(--ember)}
.p-cap{flex:0 0 46px;color:var(--ash);text-transform:uppercase;letter-spacing:.1em;font-size:.63rem}
.p-txt{flex:1 1 auto}

/* outro */
.outro{margin:64px 0 0;padding:40px 0 30px;border-top:1px solid var(--line)}
.outro .eyebrow{color:var(--ember-soft);margin-bottom:16px;display:block}
.rule{font-family:var(--font-display);font-weight:600;font-size:clamp(1.5rem,3.6vw,2.05rem);line-height:1.22;letter-spacing:-.01em;max-width:24ch}
.rule em{font-style:italic;color:var(--ember-soft);font-weight:400}
.fineprint{margin-top:24px;font-family:var(--font-mono);font-size:.74rem;line-height:1.7;color:var(--ash);max-width:62ch}

.desk{margin-top:30px;display:flex;flex-direction:column;gap:13px}
.desk-line{font-size:.98rem;color:var(--bone-dim);line-height:1.5}
.desk-tag{
  font-family:var(--font-mono);font-size:.6rem;letter-spacing:.14em;text-transform:uppercase;
  padding:4px 9px 3px;border-radius:4px;margin-right:11px;font-weight:700;white-space:nowrap;display:inline-block;
}
.desk-tag.good{background:var(--ember);color:var(--soot)}
.desk-tag.bad{border:1px solid var(--ash);color:var(--ash)}

footer{padding:46px 0 70px;text-align:center}
footer .eyebrow{color:#4a4030}

@media (max-width:640px){
  body{font-size:17px}
  .wrap{padding:0 20px}
  .hero{padding:64px 0 32px}
  .principles{grid-template-columns:1fr}
  .tier-head{gap:16px}
  .f-note{display:none}
}
@media (prefers-reduced-motion:reduce){
  .fill{transition:none}
  *{scroll-behavior:auto}
}
:focus-visible{outline:2px solid var(--ember-soft);outline-offset:3px;border-radius:3px}

/* no-bake: bars & balls */
.nb-rules{background:var(--soot-raised);border:1px solid var(--line);border-radius:12px;padding:22px 24px;margin-bottom:20px}
.nb-title{font-family:var(--font-mono);font-size:.64rem;letter-spacing:.2em;text-transform:uppercase;color:var(--ember);margin-bottom:13px}
.nb-line{display:flex;gap:12px;align-items:baseline;padding:5px 0;color:var(--bone-dim);font-size:.99rem;line-height:1.5}
.nb-mark{color:var(--ember-soft);flex:0 0 auto;font-weight:700}
.nb-line b{color:var(--bone);font-weight:600}

.recipes{display:flex;flex-direction:column;gap:16px}
.recipe{background:var(--soot-raised);border:1px solid var(--line-soft);border-radius:12px;padding:22px 24px 20px;transition:border-color .25s ease}
.recipe:hover{border-color:var(--line)}
.recipe-top{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:9px}
.r-name{font-family:var(--font-display);font-weight:600;font-size:1.34rem;letter-spacing:-.01em;line-height:1.1}
.r-tag{font-family:var(--font-mono);font-size:.6rem;letter-spacing:.16em;text-transform:uppercase;color:var(--ember-soft);border:1px solid var(--ember-deep);padding:3px 8px 2px;border-radius:4px;font-weight:700;white-space:nowrap}
.r-tag.ice{color:var(--ice);border-color:#3f5560}
.r-desc{color:var(--bone-dim);font-size:1.02rem;line-height:1.5;margin-bottom:16px}
.rstat-row{display:flex;flex-wrap:wrap;gap:14px 26px;margin-bottom:16px;padding-bottom:17px;border-bottom:1px solid var(--line-soft)}
.rstat{display:flex;flex-direction:column;gap:4px}
.rs-cap{font-family:var(--font-mono);color:var(--ash);font-size:.62rem;letter-spacing:.12em;text-transform:uppercase}
.rs-val{font-family:var(--font-mono);color:var(--bone);font-size:.82rem}
.rs-val .dots{font-size:.8rem}

.variant{margin-top:16px;padding:19px 22px;border:1px dashed var(--line);border-radius:10px;color:var(--bone-dim);font-size:.97rem;line-height:1.58}
.variant b{color:var(--bone);font-weight:600}
.v-tag{font-family:var(--font-mono);font-size:.62rem;letter-spacing:.16em;text-transform:uppercase;color:var(--ember-soft);display:block;margin-bottom:9px}

/* protein types */
.proteins{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(288px,100%),1fr));gap:14px}
.protein{background:var(--soot-raised);border:1px solid var(--line-soft);border-radius:12px;padding:20px 22px;display:flex;flex-direction:column;transition:border-color .25s ease}
.protein:hover{border-color:var(--line)}
.protein.base{border-color:#4a3320;background:linear-gradient(180deg,#241b12,var(--soot-raised))}
.pp-head{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:14px}
.pp-name{font-family:var(--font-display);font-weight:600;font-size:1.24rem;letter-spacing:-.01em;line-height:1.05}
.pp-type{font-family:var(--font-mono);font-size:.6rem;letter-spacing:.1em;text-transform:uppercase;color:var(--ash)}
.pp-suit{display:flex;flex-wrap:wrap;gap:9px 18px;margin-bottom:14px;padding-bottom:14px;border-bottom:1px solid var(--line-soft)}
.suit{display:flex;align-items:center;gap:8px;font-family:var(--font-mono);font-size:.63rem;letter-spacing:.06em;text-transform:uppercase;color:var(--ash)}
.suit .dots{font-size:.78rem}
.pp-verdict{color:var(--bone-dim);font-size:.96rem;line-height:1.5;margin-bottom:14px;flex:1 1 auto}
.pp-verdict b{color:var(--bone);font-weight:600}
.pp-traits{font-family:var(--font-mono);font-size:.68rem;line-height:1.75;color:var(--ash)}
.pp-traits b{color:var(--bone-dim);font-weight:500}
.p-mark.swap{color:var(--bone-dim)}

/* formats catalog */
.fmt-cat{margin:32px 0 15px;display:flex;align-items:baseline;gap:14px;flex-wrap:wrap}
.fmt-cat:first-child{margin-top:6px}
.fmt-cat-name{font-family:var(--font-display);font-weight:600;font-size:1.28rem;letter-spacing:-.01em}
.fmt-cat-note{font-family:var(--font-mono);font-size:.64rem;letter-spacing:.06em;text-transform:uppercase;color:var(--ash)}
.fmts{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(300px,100%),1fr));gap:14px}
.fmt{background:var(--soot-raised);border:1px solid var(--line-soft);border-radius:11px;padding:18px 20px;display:flex;flex-direction:column;transition:border-color .25s ease}
.fmt:hover{border-color:var(--line)}
.fmt-top{display:flex;align-items:baseline;gap:9px;flex-wrap:wrap;margin-bottom:8px}
.fmt-name{font-family:var(--font-display);font-weight:600;font-size:1.12rem;letter-spacing:-.01em;line-height:1.12}
.fmt-tag{font-family:var(--font-mono);font-size:.55rem;letter-spacing:.13em;text-transform:uppercase;color:var(--ember-soft);border:1px solid var(--ember-deep);padding:2px 6px 1px;border-radius:3px;font-weight:700;white-space:nowrap}
.fmt-tag.wf{color:var(--ice);border-color:#3f5560}
.fmt-blurb{color:var(--bone-dim);font-size:.93rem;line-height:1.45;margin-bottom:12px;flex:1 1 auto}
.fmt-stats{display:flex;flex-wrap:wrap;gap:6px 16px;font-family:var(--font-mono);font-size:.65rem;color:var(--ash);margin-bottom:12px;padding-bottom:12px;border-bottom:1px solid var(--line-soft)}
.fmt-stats b{color:var(--bone-dim);font-weight:500}
.fmt-stats .dots{font-size:.72rem;letter-spacing:1px;color:var(--ember-soft)}
.fmt-stats .off{color:#3c3225}
.fmt-build{font-family:var(--font-mono);font-size:.75rem;line-height:1.5;color:var(--bone-dim)}
.fmt-build .fb-mark{color:var(--ember);font-weight:700;margin-right:7px}
.fmt-swap{margin-top:10px;font-family:var(--font-mono);font-size:.72rem;line-height:1.45;color:var(--ash)}
.fmt-swap .sw{color:var(--bone-dim);font-weight:700;margin-right:5px}

:root{
  --soot:#16130d; --soot-raised:#1f1a12; --soot-sunk:#100d08;
  --line:#33291d; --line-soft:#261f16;
  --bone:#ece5d6; --bone-dim:#b3a893; --ash:#7d735f;
  --ember:#d0602e; --ember-soft:#e5924f; --ember-deep:#8f3d1c;
  --font-display:'Fraunces',Georgia,serif;
  --font-body:'Newsreader',Georgia,serif;
  --font-mono:'JetBrains Mono','SF Mono',ui-monospace,monospace;
}
*{box-sizing:border-box;margin:0;padding:0}
html{-webkit-text-size-adjust:100%}
body{
  background:var(--soot);color:var(--bone);font-family:var(--font-body);
  font-size:18px;line-height:1.6;-webkit-font-smoothing:antialiased;font-optical-sizing:auto;
  background-image:radial-gradient(120% 80% at 50% -10%, #1d1810 0%, var(--soot) 60%);
}
.wrap{max-width:700px;margin:0 auto;padding:0 22px}
.eyebrow{font-family:var(--font-mono);font-size:.82rem;letter-spacing:.28em;text-transform:uppercase;color:var(--ember-soft);font-weight:500}

header{padding:64px 0 30px}
header h1{font-family:var(--font-display);font-weight:900;font-size:clamp(2.3rem,6vw,3.4rem);line-height:1;letter-spacing:-.025em;margin:18px 0 20px}
header h1 em{font-style:italic;color:var(--ember-soft);font-weight:600}
.lede{font-size:1.12rem;color:var(--bone-dim);line-height:1.5;max-width:54ch}
.lede strong{color:var(--bone);font-weight:600}

.panel{background:var(--soot-raised);border:1px solid var(--line);border-radius:14px;padding:20px 22px 24px;margin-bottom:20px}
.tabs{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:24px}
.tab{
  flex:1 1 140px;font-family:var(--font-display);font-weight:600;font-size:1.02rem;
  background:var(--soot-sunk);color:var(--bone-dim);border:1px solid var(--line-soft);
  border-radius:9px;padding:12px 10px;cursor:pointer;transition:all .18s ease;line-height:1.15;
}
.tab:hover{color:var(--bone);border-color:var(--line)}
.tab.active{background:linear-gradient(180deg,#3a2415,#2a1c10);color:var(--bone);border-color:var(--ember-deep);box-shadow:inset 0 0 0 1px rgba(208,96,46,.25)}

.slider-top{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:14px}
.slider-label{font-family:var(--font-mono);font-size:.84rem;letter-spacing:.12em;text-transform:uppercase;color:var(--bone-dim)}
.slider-val{font-family:var(--font-display);font-weight:600;font-size:1.55rem;color:var(--ember-soft);letter-spacing:-.01em}
input[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:8px;border-radius:5px;background:var(--soot-sunk);outline:none;margin:2px 0}
input[type=range]::-webkit-slider-thumb{-webkit-appearance:none;appearance:none;width:28px;height:28px;border-radius:50%;background:var(--ember);cursor:pointer;border:4px solid var(--soot-raised);box-shadow:0 2px 7px rgba(0,0,0,.55)}
input[type=range]::-moz-range-thumb{width:22px;height:22px;border-radius:50%;background:var(--ember);cursor:pointer;border:4px solid var(--soot-raised);box-shadow:0 2px 7px rgba(0,0,0,.55)}
.ticks{display:flex;justify-content:space-between;font-family:var(--font-mono);font-size:.84rem;color:var(--ash);margin-top:8px;padding:0 2px}
.slider-yield{font-family:var(--font-mono);font-size:.92rem;color:var(--bone-dim);margin-top:14px;letter-spacing:.01em;line-height:1.5}
.slider-yield b{color:var(--ember-soft);font-weight:500}

.sheet{background:var(--soot-raised);border:1px solid var(--line);border-radius:14px;padding:22px 24px 12px;margin-bottom:16px}
.sheet-head{display:flex;justify-content:space-between;align-items:baseline;flex-wrap:wrap;gap:6px;padding-bottom:16px;margin-bottom:6px;border-bottom:1px solid var(--line)}
.sheet-title{font-family:var(--font-mono);font-size:.8rem;letter-spacing:.14em;text-transform:uppercase;color:var(--ember)}
.sheet-sub{font-family:var(--font-mono);font-size:.84rem;color:var(--ash)}

.row{display:flex;flex-wrap:wrap;justify-content:space-between;align-items:baseline;gap:8px 16px;padding:14px 0;border-bottom:1px solid var(--line-soft)}
.row:last-child{border-bottom:none}
.row-l{flex:1 1 140px}
.row-name{font-size:1.06rem;color:var(--bone);line-height:1.25}
.row-note{font-family:var(--font-mono);font-size:.86rem;color:var(--ash);line-height:1.45;margin-top:4px}
.row-note.add{color:var(--ember-soft);opacity:.9}
.row-amt{font-family:var(--font-mono);font-size:1rem;color:var(--bone-dim);text-align:right;white-space:nowrap;flex:0 0 auto;margin-left:auto}
.row-amt b{color:var(--bone);font-weight:700;font-size:1.08rem}
.approx{display:block;font-size:.92rem;color:var(--bone-dim);margin-top:3px;font-weight:400}

.meta-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:16px}
.meta-card{background:var(--soot-raised);border:1px solid var(--line-soft);border-radius:12px;padding:18px 20px}
.meta-cap{font-family:var(--font-mono);font-size:.8rem;letter-spacing:.12em;text-transform:uppercase;color:var(--ash);margin-bottom:10px}
.meta-big{font-family:var(--font-display);font-weight:600;font-size:1.55rem;color:var(--bone);letter-spacing:-.01em;line-height:1.1}
.meta-big em{font-style:normal;color:var(--ember-soft)}
.meta-line{font-family:var(--font-mono);font-size:.9rem;color:var(--bone-dim);line-height:1.6;margin-top:8px}
.meta-line b{color:var(--bone)}

.src-link{
  display:flex;align-items:center;justify-content:space-between;gap:12px;
  background:var(--soot-sunk);border:1px solid var(--line);border-radius:11px;
  padding:16px 18px;text-decoration:none;margin-bottom:18px;transition:border-color .2s ease,background .2s ease;
}
.src-link:hover{border-color:var(--ember-deep);background:#1a140d}
.src-l{min-width:0}
.src-cap{font-family:var(--font-mono);font-size:.78rem;letter-spacing:.12em;text-transform:uppercase;color:var(--ash);margin-bottom:5px}
.src-name{font-family:var(--font-body);font-size:1.02rem;color:var(--bone);line-height:1.25}
.src-arrow{color:var(--ember-soft);font-size:1.3rem;flex:0 0 auto}

.method{font-size:1rem;color:var(--bone-dim);line-height:1.55;padding:0 2px 12px}
.method b{color:var(--bone);font-weight:600}

footer{padding:30px 0 64px}
footer .fnote{font-family:var(--font-mono);font-size:.86rem;color:var(--ash);line-height:1.7;max-width:60ch}

@media(max-width:540px){
  body{font-size:17px}
  .meta-grid{grid-template-columns:1fr}
  header{padding:48px 0 26px}
}
:focus-visible{outline:2px solid var(--ember-soft);outline-offset:3px;border-radius:4px}

script:
const MIXES = {
  brownie: {
    label:'Caramel Brownies',
    boxName:'Betty Crocker Salted Caramel Brownie mix',
    link:'https://www.bettycrocker.com/products/betty-crocker-brownies-and-dessert-bars/salted-caramel',
    weight:'520 g \u00b7 18.4 oz',
    yieldPerBox:16, yieldUnit:'brownies', servingName:'brownie',
    proteinPerBox:45,
    temp:'325\u00b0F (160\u00b0C)',
    pan:'one 8\u00d78" pan (or 9\u00d79" for thinner)',
    time:'40\u201345 min at 8\u00d78" \u00b7 35\u201338 at 9\u00d79"',
    method:'<b>Stir everything but the caramel</b> until well blended \u2014 the batter runs thick, so loosen with a splash of water if it won\u2019t spread. Spread it, squeeze the caramel on top and swirl, then bake and pull them a few minutes early. Underbaked is what keeps them fudgy instead of cakey.',
    ingredients:[
      { name:'Caramel brownie mix', kind:'count', per:1, unit:'box', note:'the box itself' },
      { name:'Water', kind:'liquid', ml:50, cups:0.25, note:'as the box calls for' },
      { name:'Vegetable oil', kind:'liquid', ml:75, cups:0.3333, note:'keep the full amount \u2014 fat is what keeps them fudgy' },
      { name:'Eggs', kind:'count', per:1, unit:'', note:'the box asks for 1' },
      { name:'Egg yolk, extra', kind:'count', per:1, unit:'', note:'added \u2014 richness without turning them cakey', add:true },
      { name:'Pea protein', kind:'dry', cups:0.25, note:'added \u2014 the protein', add:true },
      { name:'Greek yogurt', kind:'dry', cups:0.1875, note:'added \u2014 moisture to offset the powder', add:true },
      { name:'Caramel pouch', kind:'count', per:1, unit:'', note:'swirl on top \u2014 comes in the box' },
    ],
  },
  banana: {
    label:'Banana Walnut Bread',
    boxName:'Betty Crocker Banana Nut / Banana Bread mix',
    link:'https://www.bettycrocker.com/products/muffin-mixes/banana-nut',
    weight:'348 g \u00b7 12.3 oz',
    yieldPerBox:12, yieldUnit:'slices', servingName:'slice',
    proteinPerBox:90,
    temp:'375\u00b0F (190\u00b0C), or 350\u00b0F gentler',
    pan:'one loaf pan (or 12 muffin cups)',
    time:'50\u201365 min for a loaf \u00b7 ~20 min for muffins',
    method:'<b>Mash the banana</b>, whisk it with the wet ingredients, then stir in the mix and pea protein just until combined. Rest the batter 8 minutes so the protein hydrates, then bake \u2014 as muffins it cooks faster and dries out less than a full loaf.',
    ingredients:[
      { name:'Banana walnut bread mix', kind:'count', per:1, unit:'box', note:'the box itself' },
      { name:'Water', kind:'liquid', ml:50, cups:0.25, note:'box calls for \u00bd cup \u2014 cut back, since banana & yogurt add moisture' },
      { name:'Vegetable oil or melted butter', kind:'liquid', ml:50, cups:0.25, note:'as the box calls for' },
      { name:'Eggs', kind:'count', per:3, unit:'', note:'box asks for 2 \u2014 +1 for protein & structure' },
      { name:'Ripe banana, mashed', kind:'banana', cups:1.0, note:'box uses \u00bd cup \u2014 doubled for moisture & to mask the powder' },
      { name:'Pea protein', kind:'dry', cups:0.5, note:'added \u2014 the protein', add:true },
      { name:'Greek yogurt', kind:'dry', cups:0.5, note:'added \u2014 keeps it moist', add:true },
    ],
  },
  muffin: {
    label:'Oatmeal Choc-Chip Muffins',
    boxName:'Quaker Oatmeal Chocolate Chip Muffin mix',
    link:'https://www.tastyrewards.com/en-ca/brands/quaker/products/quakerr-oatmeal-chocolate-chip-muffin-mix',
    weight:'900 g \u00b7 31.7 oz',
    yieldPerBox:24, yieldUnit:'muffins', servingName:'muffin',
    proteinPerBox:135,
    temp:'400\u00b0F (200\u00b0C), or 375\u00b0F gentler',
    pan:'two 12-cup muffin tins',
    time:'18\u201322 min',
    method:'<b>Whisk the eggs, yogurt, kefir and melted butter</b>, then stir in the mix and pea protein just until combined. This mix has no oil of its own, so the butter matters. Rest 8 min, keep the batter slightly loose (add a splash of water if stiff), and pull them a touch early.',
    ingredients:[
      { name:'Oatmeal choc-chip muffin mix', kind:'count', per:1, unit:'box', note:'the box itself' },
      { name:'Eggs', kind:'count', per:3, unit:'', note:'box asks for 2 \u2014 +1 for protein & structure' },
      { name:'Greek yogurt', kind:'dry', cups:0.75, note:'added \u2014 protein & moisture', add:true },
      { name:'Kefir or coconut milk', kind:'liquid', ml:120, cups:0.5, note:'added \u2014 loosens the batter', add:true },
      { name:'Melted butter', kind:'dry', cups:0.25, note:'added \u2014 this mix has no oil; fat keeps them from drying', add:true },
      { name:'Water', kind:'liquid', ml:60, cups:0.25, note:'box uses 1\u00bd cups \u2014 cut way back; yogurt, kefir & butter replace it' },
      { name:'Pea protein', kind:'dry', cups:0.5, note:'added \u2014 the protein', add:true },
    ],
  },
  cookie: {
    label:'Oatmeal Choc-Chip Cookies',
    boxName:'Betty Crocker Oatmeal Chocolate Chip Cookie mix',
    link:'https://www.bettycrocker.com/products/cookiemix/oatmealchocolatechip',
    weight:'496 g \u00b7 17.5 oz',
    yieldPerBox:24, yieldUnit:'cookies', servingName:'cookie',
    proteinPerBox:55,
    temp:'375\u00b0F (190\u00b0C)',
    pan:'ungreased cookie sheets',
    time:'11\u201313 min (rounded-tbsp cookies)',
    method:'<b>Beat the softened butter, egg and extra yolk</b>, then mix in the cookie mix and pea protein until a dough forms. If it\u2019s dry and crumbly, work in the yogurt a little at a time. Expect softer, cakier cookies \u2014 pull them looking underdone.',
    ingredients:[
      { name:'Oatmeal choc-chip cookie mix', kind:'count', per:1, unit:'box', note:'the box itself' },
      { name:'Butter, softened', kind:'dry', cups:0.5, note:'as the box calls for (1 stick)' },
      { name:'Eggs', kind:'count', per:1, unit:'', note:'the box asks for 1' },
      { name:'Egg yolk, extra', kind:'count', per:1, unit:'', note:'added \u2014 keeps them soft, not chalky', add:true },
      { name:'Pea protein', kind:'dry', cups:0.25, note:'added \u2014 \u2153 cup max, or they crumble', add:true },
      { name:'Greek yogurt', kind:'dry', cups:0.125, note:'added \u2014 binds the drier dough', add:true },
    ],
  },
};

var CUP_FR = [[0,''],[1/8,'\u215b'],[1/6,'\u2159'],[1/4,'\u00bc'],[1/3,'\u2153'],[3/8,'\u215c'],[1/2,'\u00bd'],[5/8,'\u215d'],[2/3,'\u2154'],[3/4,'\u00be'],[5/6,'\u215a'],[7/8,'\u215e'],[1,'']];
function fmtCups(c){
  if(c < 0.0001) return '0';
  var whole = Math.floor(c + 1e-6), frac = c - whole, best=null, bd=1;
  for(var i=0;i<CUP_FR.length;i++){ var d=Math.abs(frac-CUP_FR[i][0]); if(d<bd){bd=d;best=CUP_FR[i];} }
  if(bd <= 0.017){
    var carry = (best[0]===1)?1:0, w = whole+carry, s = carry?'':best[1];
    if(w>0 && s) return w+s+' cups';
    if(w>0) return w+' cup'+(w>1?'s':'');
    if(s) return s+' cup';
    return '0';
  }
  var tbsp = c*16, rt = Math.round(tbsp*2)/2;
  if(rt >= 1) return rt+' tbsp';
  return (Math.round(c*48*2)/2)+' tsp';
}
var CT_FR = [[0,''],[1/4,'\u00bc'],[1/3,'\u2153'],[1/2,'\u00bd'],[2/3,'\u2154'],[3/4,'\u00be']];
function fmtCount(n){
  var whole = Math.floor(n + 1e-6), frac = n - whole, best=null, bd=1;
  for(var i=0;i<CT_FR.length;i++){ var d=Math.abs(frac-CT_FR[i][0]); if(d<bd){bd=d;best=CT_FR[i];} }
  if(bd > 0.04){ return (Math.round(n*10)/10)+''; }
  var w = whole, s = best[1];
  if(w>0 && s) return w+s;
  if(w>0) return ''+w;
  if(s) return s;
  return '0';
}

var curWeight = '';
function amount(ing, m){
  if(ing.kind==='count'){
    var base = '<b>'+fmtCount(ing.per*m)+'</b>'+(ing.unit?' '+ing.unit+(ing.per*m>1&&ing.unit==='box'?'es':''):'');
    if(ing.unit==='box' && curWeight){ base += '<span class="approx">'+curWeight+' per box</span>'; }
    return base;
  }
  if(ing.kind==='liquid'){
    return '<b>'+Math.round(ing.ml*m)+' mL</b><span class="approx">'+fmtCups(ing.cups*m)+'</span>';
  }
  if(ing.kind==='dry'){
    var cups = ing.cups*m;
    if(cups < 0.245){ return '<b>'+(Math.round(cups*16*2)/2)+' tbsp</b>'; }
    return '<b>'+fmtCups(cups)+'</b>';
  }
  if(ing.kind==='banana'){
    var med = Math.round(ing.cups*m/0.5);
    return '<b>'+fmtCups(ing.cups*m)+' mashed</b><span class="approx">about '+med+' medium</span>';
  }
  return '';
}

var state = { mix:'brownie', mult:1 };
var slider = document.getElementById('slider');
function boxWord(m){ return fmtCount(m) + ' box' + (m>1?'es':''); }

function render(){
  var mx = MIXES[state.mix], m = state.mult;
  curWeight = mx.weight;

  document.getElementById('sval').textContent = boxWord(m);
  var yld = Math.round(mx.yieldPerBox * m);
  var scaleNote = (m>1) ? ' <b>(scale the pans, keep the time)</b>' : '';
  document.getElementById('syield').innerHTML = '\u2192 makes about <b>'+yld+' '+mx.yieldUnit+'</b>'+scaleNote;
  document.getElementById('sheetsub').textContent = mx.label + ' \u00b7 ' + boxWord(m);

  document.getElementById('rows').innerHTML = mx.ingredients.map(function(ing){
    return '<div class="row"><div class="row-l"><div class="row-name">'+ing.name+'</div>'+
           '<div class="row-note'+(ing.add?' add':'')+'">'+ing.note+'</div></div>'+
           '<div class="row-amt">'+amount(ing, m)+'</div></div>';
  }).join('');

  document.getElementById('bakecard').innerHTML =
    '<div class="meta-cap">Bake it</div>'+
    '<div class="meta-big">'+mx.temp+'</div>'+
    '<div class="meta-line"><b>'+mx.pan+'</b><br>'+mx.time+'</div>';

  var total = Math.round(mx.proteinPerBox * m);
  var per = Math.round(mx.proteinPerBox / mx.yieldPerBox);
  document.getElementById('protcard').innerHTML =
    '<div class="meta-cap">Protein (approx)</div>'+
    '<div class="meta-big"><em>~'+total+' g</em> total</div>'+
    '<div class="meta-line">about <b>~'+per+' g</b> per '+mx.servingName+'<br>across '+yld+' '+mx.yieldUnit+'</div>';

  document.getElementById('srclink').href = mx.link;
  document.getElementById('srcname').textContent = mx.boxName;
  document.getElementById('method').innerHTML = mx.method;

  var pct = ((m - 0.5) / (4 - 0.5)) * 100;
  slider.style.background = 'linear-gradient(90deg, var(--ember) 0%, var(--ember) '+pct+'%, var(--soot-sunk) '+pct+'%, var(--soot-sunk) 100%)';
}

document.querySelectorAll('.tab').forEach(function(t){
  t.addEventListener('click', function(){
    document.querySelectorAll('.tab').forEach(function(x){ x.classList.remove('active'); });
    t.classList.add('active');
    state.mix = t.dataset.mix;
    render();
  });
});
slider.addEventListener('input', function(){ state.mult = parseFloat(slider.value); render(); });

render();
